@dataclass
class UISession:
    """UI session management"""
    session_id: str
    start_time: datetime
    requests_made: int
    total_revenue: float
    last_activity: datetime

class OASISUIManager:
    """Main UI manager for OASIS frontend"""

    def __init__(self):
        # API configuration
        self.api_base_url = "https://your-api-processor-space.hf.space"  # Replace with actual URL
        self.orchestrator_url = "https://your-orchestrator-space.hf.space"  # Replace with actual URL

        # Session management
        self.session = UISession(
            session_id=f"ui_{int(time.time())}",
            start_time=datetime.now(),
            requests_made=0,
            total_revenue=0.0,
            last_activity=datetime.now()
        )

        # UI statistics
        self.ui_stats = {
            "interface_loads": 0,
            "api_calls_made": 0,
            "errors_encountered": 0,
            "total_processing_time": 0.0,
            "start_time": datetime.now()
        }

        logger.info(f"OASIS UI Manager initialized with session: {self.session.session_id}")

    def call_api(self, endpoint: str, method: str = "GET", data: Dict = None) -> Dict[str, Any]:
        """Make API calls to the processing backend"""
        try:
            url = f"{self.api_base_url}{endpoint}"

            self.session.requests_made += 1
            self.session.last_activity = datetime.now()
            self.ui_stats["api_calls_made"] += 1

            if method == "POST":
                response = requests.post(url, json=data, timeout=30)
            else:
                response = requests.get(url, timeout=30)

            if response.status_code == 200:
                result = response.json()

                # Track revenue if present
                if isinstance(result, dict) and "revenue_generated" in result:
                    self.session.total_revenue += result["revenue_generated"]

                return {"success": True, "data": result}
            else:
                error_msg = f"API Error: {response.status_code}"
                self.ui_stats["errors_encountered"] += 1
                return {"success": False, "error": error_msg}

        except Exception as e:
            logger.error(f"API call failed: {str(e)}")
            self.ui_stats["errors_encountered"] += 1
            return {"success": False, "error": str(e)}

    def get_session_info(self) -> Dict[str, Any]:
        """Get current session information"""
        uptime = datetime.now() - self.session.start_time

        return {
            "session_id": self.session.session_id,
            "uptime": str(uptime),
            "requests_made": self.session.requests_made,
            "total_revenue": round(self.session.total_revenue, 2),
            "last_activity": self.session.last_activity.strftime("%H:%M:%S"),
            "ui_stats": self.ui_stats
        }

# Initialize UI manager
